import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, StripeInvoiceFinalizedPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      realmId: 'test-realm',
      accessToken: 'test-token',
      defaultCustomerId: '1',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeInvoiceFinalizedPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.invoiceId).toBe('123');
    expect(result.attachmentId).toBe('456');
  });
});

describe('happy path', () => {
  it('creates invoice and attachment with correct request bodies', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) {
        expect(req.method).toBe('POST');
        expect(req.headers.get('authorization')).toBe('Bearer test-token');
        const body = req.json as Record<string, unknown>;
        expect(body).toMatchObject({
          DocNumber: 'in_123',
          Currency: 'USD',
          CustomerRef: { value: '42' },
          CustomField: [{ DefinitionId: '1', StringValue: 'https://pay.stripe.com/invoice/in_123' }],
        });
        expect(Array.isArray(body.Line)).toBe(true);
        const line0 = body.Line[0] as Record<string, unknown>;
        expect(line0).toMatchObject({
          Description: 'Test Item',
          Amount: 12.99,
          DetailType: 'SalesItemLineDetail',
          SalesItemLineDetail: { ItemRef: { value: '1', name: 'Service' } },
        });
        return jsonResponse({ Invoice: { Id: '999', DocNumber: 'in_123' } }, 201);
      }
      if (req.url.endsWith('/attachment')) {
        expect(req.method).toBe('POST');
        expect(req.headers.get('authorization')).toBe('Bearer test-token');
        const body = req.json as Record<string, unknown>;
        expect(body).toMatchObject({
          AttachableRef: [{ EntityRef: { type: 'Invoice', value: '999' } }],
          FileName: 'stripe_invoice.txt',
          ContentType: 'text/plain',
          ByteOrder: 'LittleEndian',
          Content: 'aHR0cHM6Ly9wYXkuc3RyaXBlLmNvbS9pbnZvaWNlL2luXzEyMw==',
        });
        return jsonResponse({ Attachment: { Id: '888' } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: StripeInvoiceFinalizedPayload = {
      id: 'in_123',
      customer: { email: 'test@example.com' },
      lines: {
        data: [
          { description: 'Test Item', amount: 1299, currency: 'usd' },
        ],
      },
      url: 'https://pay.stripe.com/invoice/in_123',
    };

    const config: ConnectorConfig = {
      realmId: 'test-realm',
      accessToken: 'test-token',
      defaultCustomerId: '42',
      fetch,
    };

    const result = await handle(payload, config);
    expect(result.invoiceId).toBe('999');
    expect(result.attachmentId).toBe('888');
    expect(calls.length).toBe(2);
  });
});

describe('auth mechanism', () => {
  it('sends Bearer token in Authorization header for both requests', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer secret-123');
      if (req.url.endsWith('/invoice')) return jsonResponse({ Invoice: { Id: '1' } }, 201);
      if (req.url.endsWith('/attachment')) return jsonResponse({ Attachment: { Id: '2' } }, 201);
      return jsonResponse({}, 404);
    });

    const payload: StripeInvoiceFinalizedPayload = {
      id: 'in_1',
      customer: { email: 'a@b.com' },
      lines: { data: [{ description: 'x', amount: 100, currency: 'usd' }] },
      url: 'https://pay.stripe.com/invoice/in_1',
    };

    await handle(payload, {
      realmId: 'r',
      accessToken: 'secret-123',
      defaultCustomerId: '1',
      fetch,
    });

    expect(calls.length).toBe(2);
  });
});

describe('field mapping', () => {
  it('maps Stripe fields to QuickBooks invoice correctly', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) {
        const body = req.json as Record<string, unknown>;
        expect(body.DocNumber).toBe('in_map');
        expect(body.Currency).toBe('EUR');
        expect((body.CustomerRef as Record<string, unknown>).value).toBe('cust-99');
        expect((body.CustomField as unknown[])[0]).toMatchObject({
          DefinitionId: '9',
          StringValue: 'https://pay.stripe.com/invoice/in_map',
        });
        const line0 = (body.Line as unknown[])[0] as Record<string, unknown>;
        expect(line0.Description).toBe('Mapped Item');
        expect(line0.Amount).toBe(42.5);
        expect(((line0.SalesItemLineDetail as Record<string, unknown>).ItemRef as Record<string, unknown>).value).toBe('svc-5');
        return jsonResponse({ Invoice: { Id: '1' } }, 201);
      }
      if (req.url.endsWith('/attachment')) return jsonResponse({ Attachment: { Id: '2' } }, 201);
      return jsonResponse({}, 404);
    });

    const payload: StripeInvoiceFinalizedPayload = {
      id: 'in_map',
      customer: { email: 'ignored@email.com' },
      lines: { data: [{ description: 'Mapped Item', amount: 4250, currency: 'eur' }] },
      url: 'https://pay.stripe.com/invoice/in_map',
    };

    await handle(payload, {
      realmId: 'r',
      accessToken: 't',
      defaultCustomerId: 'cust-99',
      serviceItemId: 'svc-5',
      customFieldDefinitionId: '9',
      fetch,
    });

    const invoiceCallBody = calls[0].json as Record<string, unknown>;
    expect(invoiceCallBody).toMatchObject({
      DocNumber: 'in_map',
      Currency: 'EUR',
      CustomerRef: { value: 'cust-99' },
      CustomField: [{ DefinitionId: '9', StringValue: 'https://pay.stripe.com/invoice/in_map' }],
      Line: [{
        Description: 'Mapped Item',
        Amount: 42.5,
        SalesItemLineDetail: { ItemRef: { value: 'svc-5', name: 'Service' } },
      }],
    });
  });
});

describe('missing required fields', () => {
  it('throws on missing id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, id: undefined } as unknown as StripeInvoiceFinalizedPayload;
    await expect(handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })).rejects.toThrow(
      'Missing required field: id'
    );
  });

  it('throws on missing customer.email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, customer: {} } as unknown as StripeInvoiceFinalizedPayload;
    await expect(handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })).rejects.toThrow(
      'Missing required field: customer.email'
    );
  });

  it('throws on missing lines.data', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, lines: { data: [] } } as unknown as StripeInvoiceFinalizedPayload;
    await expect(handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })).rejects.toThrow(
      'Missing required field: lines.data (must be non-empty array)'
    );
  });

  it('throws on missing url', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, url: undefined } as unknown as StripeInvoiceFinalizedPayload;
    await expect(handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })).rejects.toThrow(
      'Missing required field: url'
    );
  });
});

describe('non-2xx target response', () => {
  it('throws with status and endpoint on invoice creation failure', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401));
    const payload: StripeInvoiceFinalizedPayload = {
      id: 'in_1',
      customer: { email: 'a@b.com' },
      lines: { data: [{ description: 'x', amount: 100, currency: 'usd' }] },
      url: 'https://pay.stripe.com/invoice/in_1',
    };
    await expect(
      handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })
    ).rejects.toThrow('QuickBooks create invoice failed: 401 Unauthorized at https://quickbooks.api.intuit.com/v3/company/r/invoice');
  });

  it('throws with status and endpoint on attachment failure', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) return jsonResponse({ Invoice: { Id: '1' } }, 201);
      return jsonResponse({ error: 'server error' }, 500);
    });
    const payload: StripeInvoiceFinalizedPayload = {
      id: 'in_1',
      customer: { email: 'a@b.com' },
      lines: { data: [{ description: 'x', amount: 100, currency: 'usd' }] },
      url: 'https://pay.stripe.com/invoice/in_1',
    };
    await expect(
      handle(payload, { realmId: 'r', accessToken: 't', defaultCustomerId: '1', fetch })
    ).rejects.toThrow('QuickBooks attach document failed: 500 Internal Server Error at https://quickbooks.api.intuit.com/v3/company/r/attachment');
  });
});

